script:
todo = doc.allocated_to

value = frappe.get_doc(doc.reference_type,doc.reference_name)

if doc.status == "Cancelled":

    t = value.mentor
    value.mentor = []

    for x in t:
        if x.user_name!=todo:
            value.append("mentor",{"user_name":x.user_name})

else:
    value.append("mentor",{"user_name":todo})

value.save()
